test('virtual SMS list preserves an unselected reader scroll anchor when polling prepends a reply', async ({
  page,
}) => {
  const errors: string[] = []
  page.on('pageerror', (error) => errors.push(error.message))
  rows = Array.from({ length: 80 }, (_, i) =>
    row(
      `r${String(79 - i).padStart(3, '0')}`,
      `existing reply ${79 - i}`,
      new Date(Date.UTC(2026, 8, 20, 1, 0, 0) + (79 - i) * 1000).toISOString(),
    ),
  )

  await page.setViewportSize({ width: 1280, height: 800 })
  await page.clock.install()
  await page.goto(`${origin}/virtual`)

  const listbox = page.getByRole('listbox', { name: 'SMS' })
  await expect(page.getByLabel('Communication total')).toHaveText('80')
  await expect(listbox.getByRole('option')).not.toHaveCount(0)
  await page.getByLabel('Unsent draft').fill('unsent reply')
  await listbox.evaluate((element) => {
    element.scrollTop = 1200
  })
  await expect.poll(() => listbox.evaluate((element) => element.scrollTop)).toBe(1200)

  const anchorBefore = await listbox.evaluate((element) => {
    const viewport = element.getBoundingClientRect()
    const option = Array.from(element.querySelectorAll<HTMLElement>('[role="option"]')).find(
      (candidate) => {
        const rect = candidate.getBoundingClientRect()
        return rect.bottom > viewport.top && rect.top < viewport.bottom
      },
    )
    if (!option) return null
    return { id: option.id, top: option.getBoundingClientRect().top - viewport.top }
  })
  expect(anchorBefore).not.toBeNull()

  rows = [row('new', 'late inbound reply', '2026-09-20T02:00:00.000Z'), ...rows]

  const refreshed = page.waitForResponse(
    (response) => new URL(response.url()).pathname === '/__communications',
  )
  await page.clock.runFor(60_000)
  const response = await refreshed
  await response.finished()
  await page.clock.resume()

  await expect(page.getByLabel('Communication total')).toHaveText('81')
  await expect(page.getByLabel('Unsent draft')).toHaveValue('unsent reply')

  const anchorAfter = await listbox.evaluate((element) => {
    const viewport = element.getBoundingClientRect()
    const option = Array.from(element.querySelectorAll<HTMLElement>('[role="option"]')).find(
      (candidate) => {
        const rect = candidate.getBoundingClientRect()
        return rect.bottom > viewport.top && rect.top < viewport.bottom
      },
    )
    if (!option) return null
    return { id: option.id, top: option.getBoundingClientRect().top - viewport.top }
  })
  expect(anchorAfter).not.toBeNull()

  console.log('MessageList polling anchor', { before: anchorBefore, after: anchorAfter })
  expect.soft(anchorAfter!.id).toBe(anchorBefore!.id)
  expect.soft(Math.abs(anchorAfter!.top - anchorBefore!.top)).toBeLessThanOrEqual(1)
  expect(errors).toEqual([])
})

