import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { act, renderHook } from '@testing-library/react'
import {
  QueryClient,
  QueryClientProvider,
  focusManager,
  type InfiniteData,
} from '@tanstack/react-query'
import type { ReactNode } from 'react'
import type { Communication } from '@/types/entities'
import { fromCommunication } from './mailItems'

let table: Communication[]
let failNextHead: Error | null
let failNextRange: Error | null
let headCalls: number[]
let rangeCalls: Array<[number, number]>
let exactCountSelections: number

const rangeMock = vi.fn((from: number, to: number) => {
  rangeCalls.push([from, to])
  if (failNextRange) {
    const error = failNextRange
    failNextRange = null
    return Promise.resolve({ data: null, error })
  }
  return Promise.resolve({ data: table.slice(from, to + 1), error: null })
})

vi.mock('@/lib/supabase', () => ({
  supabase: {
    from: () => {
      const chain = {
        select: (_columns: string, options?: { count?: string }) => {
          if (options?.count === 'exact') exactCountSelections += 1
          return chain
        },
        order: () => chain,
        limit: (value: number) => {
          headCalls.push(value)
          if (failNextHead) {
            const error = failNextHead
            failNextHead = null
            return Promise.resolve({ data: null, error, count: null })
          }
          return Promise.resolve({
            data: table.length > 0 ? [{ id: table[0].id }] : [],
            error: null,
            count: table.length,
          })
        },
        eq: () => Promise.resolve({ error: null }),
        gte: () => chain,
        update: () => chain,
        range: rangeMock,
      }
      return chain
    },
  },
}))

vi.mock('@/services/emailService', () => ({ emailService: {} }))
vi.mock('@/services/emailLinkService', () => ({}))

import {
  COMMUNICATIONS_PAGE_SIZE,
  INBOX_REFETCH_MS,
  MAIL_KEYS,
  useCommunications,
  useSetRead,
  type CommunicationsPage,
} from './useMailData'

function comm(id: string, body: string, createdAt: string): Communication {
  return {
    id,
    channel: 'sms',
    direction: 'inbound',
    body,
    status: 'delivered',
    is_read: false,
    sender_name: '+61400000000',
    recipient_phone: '+61411111111',
    created_at: createdAt,
    updated_at: createdAt,
  }
}

function rows(length: number): Communication[] {
  return Array.from({ length }, (_, index) =>
    comm(
      `r${String(length - 1 - index).padStart(3, '0')}`,
      `row ${length - 1 - index}`,
      new Date(Date.UTC(2026, 8, 20, 2, 0, 0) + (length - 1 - index) * 1000).toISOString(),
    ),
  )
}

function makeClient() {
  return new QueryClient({ defaultOptions: { queries: { retry: false } } })
}

function wrapperFor(client: QueryClient) {
  return function Wrapper({ children }: { children: ReactNode }) {
    return <QueryClientProvider client={client}>{children}</QueryClientProvider>
  }
}

async function settle(ms = 0) {
  await act(async () => {
    if (ms > 0) await vi.advanceTimersByTimeAsync(ms)
    for (let i = 0; i < 5; i++) {
      await new Promise((resolve) => setTimeout(resolve, 0))
    }
  })
}

async function poll(ms: number = INBOX_REFETCH_MS) {
  await settle(ms)
}

describe('useCommunications polling (crm7#2594 C4)', () => {
  let client: QueryClient

  beforeEach(() => {
    vi.useFakeTimers({ toFake: ['setInterval', 'clearInterval', 'Date'] })
    focusManager.setFocused(true)
    table = []
    failNextHead = null
    failNextRange = null
    headCalls = []
    rangeCalls = []
    exactCountSelections = 0
    rangeMock.mockClear()
    client = makeClient()
  })

  afterEach(() => {
    client.clear()
    focusManager.setFocused(undefined)
    vi.useRealTimers()
  })

  it('picks up a new inbound SMS on the next poll without a remount', async () => {
    table = [comm('older', 'first reply', '2026-09-20T01:00:00.000Z')]
    const view = renderHook(() => useCommunications(true), {
      wrapper: wrapperFor(client),
    })
    await settle()
    expect(view.result.current.data.items.map((item) => item.id)).toEqual(['communication:older'])

    table = [comm('newer', 'second reply', '2026-09-20T01:01:00.000Z'), ...table]
    await poll()

    expect(view.result.current.data.items.map((item) => item.id)).toEqual([
      'communication:newer',
      'communication:older',
    ])
    expect(view.result.current.data.total).toBe(2)
    view.unmount()
  })

  it('uses only one exact-count head probe per unchanged interval after two pages load', async () => {
    table = rows(101)
    const view = renderHook(() => useCommunications(true), {
      wrapper: wrapperFor(client),
    })
    await settle()
    await act(async () => {
      await view.result.current.fetchNextPage()
    })
    await settle()
    expect(view.result.current.data.items).toHaveLength(101)

    headCalls = []
    rangeCalls = []
    exactCountSelections = 0
    await poll()
    expect(headCalls).toEqual([1])
    expect(exactCountSelections).toBe(1)
    expect(rangeCalls).toEqual([])

    await poll()
    expect(headCalls).toEqual([1, 1])
    expect(exactCountSelections).toBe(2)
    expect(rangeCalls).toEqual([])
    view.unmount()
  })

  it('refreshes every retained page after a changed head with one exact count and no duplicates', async () => {
    table = rows(101)
    const view = renderHook(() => useCommunications(true), {
      wrapper: wrapperFor(client),
    })
    await settle()
    await act(async () => {
      await view.result.current.fetchNextPage()
    })
    await settle()
    expect(view.result.current.data.items).toHaveLength(101)

    table = [comm('newest', 'late reply', '2026-09-20T03:00:00.000Z'), ...table]
    headCalls = []
    rangeCalls = []
    exactCountSelections = 0
    await poll()

    expect(headCalls).toEqual([1])
    expect(exactCountSelections).toBe(1)
    expect(rangeCalls).toEqual([
      [0, 99],
      [100, 199],
    ])
    const ids = view.result.current.data.items.map((item) => item.id)
    expect(new Set(ids).size).toBe(ids.length)
    expect(ids).toHaveLength(102)
    expect(view.result.current.data.total).toBe(102)
    expect(view.result.current.hasNextPage).toBe(false)
    view.unmount()
  })

  it('does not probe or load while disabled and stops both after disabling again', async () => {
    table = [comm('a', 'x', '2026-09-20T01:00:00.000Z')]
    const view = renderHook(({ enabled }) => useCommunications(enabled), {
      wrapper: wrapperFor(client),
      initialProps: { enabled: false },
    })
    await settle()
    await poll()
    expect(headCalls).toEqual([])
    expect(rangeCalls).toEqual([])

    view.rerender({ enabled: true })
    await settle()
    expect(headCalls.length).toBeGreaterThanOrEqual(1)
    expect(rangeCalls.length).toBeGreaterThanOrEqual(1)

    view.rerender({ enabled: false })
    await settle()
    const headCallsAfterDisable = headCalls.length
    const rangeCallsAfterDisable = rangeCalls.length
    await poll()
    await poll()
    expect(headCalls).toHaveLength(headCallsAfterDisable)
    expect(rangeCalls).toHaveLength(rangeCallsAfterDisable)
    view.unmount()
  })

  it('retains items through a head failure and public refetch recovers head and pages', async () => {
    table = [comm('a', 'x', '2026-09-20T01:00:00.000Z')]
    const view = renderHook(() => useCommunications(true), {
      wrapper: wrapperFor(client),
    })
    await settle()
    expect(view.result.current.data.items.map((item) => item.id)).toEqual(['communication:a'])

    failNextHead = new Error('head transient')
    await poll()
    expect(view.result.current.error).toMatchObject({ message: 'head transient' })
    expect(view.result.current.data.items.map((item) => item.id)).toEqual(['communication:a'])

    table = [comm('b', 'y', '2026-09-20T01:02:00.000Z'), ...table]
    await act(async () => {
      await view.result.current.refetch()
    })
    await settle()
    expect(view.result.current.error).toBeNull()
    expect(view.result.current.data.items.map((item) => item.id)).toEqual([
      'communication:b',
      'communication:a',
    ])
    expect(view.result.current.data.total).toBe(2)
    view.unmount()
  })

  it('retries failed history on a later unchanged successful head probe', async () => {
    table = [comm('a', 'x', '2026-09-20T01:00:00.000Z')]
    const view = renderHook(() => useCommunications(true), {
      wrapper: wrapperFor(client),
    })
    await settle()

    table = [comm('b', 'y', '2026-09-20T01:02:00.000Z'), ...table]
    failNextRange = new Error('history transient')
    await poll()
    expect(view.result.current.error).toMatchObject({ message: 'history transient' })
    expect(view.result.current.data.items.map((item) => item.id)).toEqual(['communication:a'])
    expect(view.result.current.data.total).toBe(2)

    rangeCalls = []
    exactCountSelections = 0
    await poll()
    expect(exactCountSelections).toBe(1)
    expect(rangeCalls).toEqual([[0, 99]])
    expect(view.result.current.error).toBeNull()
    expect(view.result.current.data.items.map((item) => item.id)).toEqual([
      'communication:b',
      'communication:a',
    ])
    view.unmount()
  })

  it('refetches stale data on window-focus recovery without manual refetch', async () => {
    table = [comm('a', 'x', '2026-09-20T01:00:00.000Z')]
    const view = renderHook(() => useCommunications(true), {
      wrapper: wrapperFor(client),
    })
    await settle()
    expect(view.result.current.data.items).toHaveLength(1)

    focusManager.setFocused(false)
    table = [comm('b', 'y', '2026-09-20T01:01:00.000Z'), ...table]
    await vi.advanceTimersByTimeAsync(31_000)
    await settle()
    expect(view.result.current.data.items.map((item) => item.id)).toEqual(['communication:a'])

    focusManager.setFocused(true)
    await settle()
    expect(view.result.current.data.items.map((item) => item.id)).toEqual([
      'communication:b',
      'communication:a',
    ])
    view.unmount()
  })

  it('keeps head cache shape separate from optimistic communication-page updates', async () => {
    const communication = comm('a', 'x', '2026-09-20T01:00:00.000Z')
    const item = fromCommunication(communication)
    const head = { latestId: communication.id, total: 1 }
    client.setQueryData(MAIL_KEYS.communicationsHead, head)
    client.setQueryData<InfiniteData<CommunicationsPage>>(MAIL_KEYS.communications, {
      pages: [{ items: [item], total: 1, page: 0 }],
      pageParams: [0],
    })
    const view = renderHook(() => useSetRead(), { wrapper: wrapperFor(client) })

    await act(async () => {
      await view.result.current.mutateAsync({ item, read: true })
    })

    expect(client.getQueryData(MAIL_KEYS.communicationsHead)).toEqual(head)
    expect(client.getQueryData(MAIL_KEYS.communicationsHead)).not.toHaveProperty('pages')
    expect(
      client.getQueryData<InfiniteData<CommunicationsPage>>(MAIL_KEYS.communications)?.pages[0]
        .items[0].isRead,
    ).toBe(true)
    expect(COMMUNICATIONS_PAGE_SIZE).toBe(100)
    view.unmount()
  })
})

