export function useCommunications(enabled: boolean) {
  const qc = useQueryClient()
  const previousHead = useRef<CommunicationsHead | null>(null)
  const head = useQuery({
    queryKey: MAIL_KEYS.communicationsHead,
    queryFn: fetchCommunicationsHead,
    enabled,
    refetchInterval: INBOX_REFETCH_MS,
    refetchOnWindowFocus: true,
    staleTime: 30_000,
  })
  const query = useInfiniteQuery({
    queryKey: MAIL_KEYS.communications,
    queryFn: ({ pageParam }) =>
      fetchCommunicationsPage(
        pageParam,
        qc.getQueryData<CommunicationsHead>(MAIL_KEYS.communicationsHead)?.total ?? 0,
      ),
    initialPageParam: 0,
    getNextPageParam: (last, _pages, lastPageParam) =>
      nextCommunicationsPageParam(last, lastPageParam),
    enabled: enabled && head.data !== undefined,
    staleTime: 30_000,
  })
  useEffect(() => {
    if (!enabled || !head.data) return
    const previous = previousHead.current
    const changed =
      previous !== null &&
      (previous.latestId !== head.data.latestId || previous.total !== head.data.total)
    previousHead.current = head.data
    const failed = qc.getQueryState(MAIL_KEYS.communications)?.status === 'error'
    if (changed || failed) {
      void qc.invalidateQueries({ queryKey: MAIL_KEYS.communications, exact: true })
    }
  }, [enabled, head.data, head.dataUpdatedAt, qc])

  const items = flattenCommunicationsPages(query.data?.pages ?? [])
  const total = head.data?.total ?? query.data?.pages[0]?.total ?? items.length

  return {
    data: {
      items,
      total,
      pageSize: COMMUNICATIONS_PAGE_SIZE,
      hasMore: Boolean(query.hasNextPage),
    },
    isLoading: head.isLoading || query.isLoading,
    isFetching: head.isFetching || query.isFetching,
    isFetchingNextPage: query.isFetchingNextPage,
    hasNextPage: Boolean(query.hasNextPage),
    fetchNextPage: query.fetchNextPage,
    error: query.error ?? head.error,
    refetch: async () => {
      await head.refetch()
      return query.refetch()
    },
  }
}

